import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
const module={exports:{}};
vm.runInNewContext(ts.transpileModule(fs.readFileSync('src/lib/jobPurchaseOrderAllocation.ts','utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText,{module,exports:module.exports});
const {allocateCommittedPOCosts}=module.exports;
const po={id:'po1',productId:'speaker',quantity:12,unitPrice:90,documentType:'po',status:'submitted'};
const lines=[{id:'a',productId:'speaker',quantity:4}];
const links=[
 {poItemId:'po1',salesOrderId:'job1',salesOrderLineId:'a',productId:'speaker',quantity:4},
 {poItemId:'po1',salesOrderId:'job2',salesOrderLineId:'b',productId:'speaker',quantity:3},
 {poItemId:'po1',salesOrderId:'job3',salesOrderLineId:'c',productId:'speaker',quantity:5}
];
let r=allocateCommittedPOCosts('job1',lines,[po],links);
assert.equal(r.allocations[0].orderedQuantity,4);
assert.equal(r.allocations[0].orderedUnitCost,90);
assert.equal(r.needsReview.length,0);
r=allocateCommittedPOCosts('job1',lines,[po],[...links,{...links[0],quantity:1}]);
assert.equal(r.allocations[0].orderedQuantity,0);
assert.ok(r.needsReview.some(x=>x.includes('over-allocated-po')));
r=allocateCommittedPOCosts('job1',lines,[po],[links[0]]);
assert.ok(r.needsReview.some(x=>x.includes('unallocated-quantity')));
r=allocateCommittedPOCosts('job1',lines,[{...po,status:'draft'}],links);
assert.equal(r.allocations[0].orderedQuantity,0);
const sql=fs.readFileSync('supabase/migrations/20261123110000_po_line_allocations.sql','utf8');
assert.match(sql,/CREATE TABLE IF NOT EXISTS public\.po_line_allocations/);
assert.match(sql,/ENABLE ROW LEVEL SECURITY/);
assert.match(sql,/PO line quantity over-allocated/);
assert.match(sql,/Sales order line quantity over-allocated/);
assert.match(sql,/FROM public\.po_items WHERE id=NEW\.po_item_id FOR UPDATE/);
assert.match(sql,/FROM public\.proposal_line_items WHERE id=NEW\.proposal_line_item_id FOR UPDATE/);
assert.match(sql,/Cannot reduce PO quantity below allocated quantity/);
const sales=fs.readFileSync('src/components/Sales/SalesOrderProductsTab.tsx','utf8');
assert.match(sales,/proposal_line_item_id: item\.id/);
assert.doesNotMatch(sales,/summarized\.set\(item\.product_id/);
assert.match(sql,/ALTER TABLE public\.product_request_items/);
assert.match(sql,/CREATE TRIGGER allocate_request_backed_po_line_insert/);
assert.match(sql,/request_line\.proposal_line_item_id/);
assert.match(sql,/parent_request\.sales_order_id/);
assert.match(sql,/product or quantity does not match source/);
assert.match(sql,/CREATE OR REPLACE FUNCTION public\.assign_po_line_allocations/);
assert.match(sql,/public\.can_manage_purchasing\(\)/);
assert.match(sql,/target\.status <> 'draft'/);
assert.match(sql,/REVOKE ALL ON FUNCTION public\.assign_po_line_allocations/);
assert.match(sql,/CREATE OR REPLACE FUNCTION public\.get_unallocated_sales_order_products/);
assert.match(sql,/so\.organization_id=org AND li\.organization_id=org/);
assert.match(sql,/po\.status NOT IN \('cancelled','canceled','void'\)/);
assert.match(sql,/CREATE TRIGGER protect_allocated_po_line_identity_write/);
assert.match(sql,/CREATE TRIGGER protect_allocated_sales_order_line_quantity_write/);
assert.match(sql,/a.sales_order_id=NEW.sales_order_id/);
assert.match(sql,/CREATE TRIGGER prevent_allocated_po_line_delete_write/);
assert.match(sql,/CREATE TRIGGER prevent_allocated_source_product_change_write/);
assert.match(sql,/CREATE OR REPLACE FUNCTION public\.create_consolidated_job_purchase_order/);
assert.match(sql,/public\.create_request_purchase_document\(/);
assert.match(sql,/INSERT INTO public\.po_line_allocations\(/);
const purchasing=fs.readFileSync('src/components/Inventory/PurchaseOrders.tsx','utf8');
assert.match(purchasing,/create_consolidated_job_purchase_order/);
assert.match(purchasing,/Create consolidated vendor PO/);
assert.match(sql,/Selected equipment does not belong to the chosen vendor/);
assert.match(purchasing,/demandRetry\.current=crypto\.randomUUID\(\)/);
assert.match(sql,/CREATE TRIGGER validate_po_reactivation_allocations_write/);
assert.match(sql,/Cannot reactivate PO: equipment was reordered after cancellation/);
assert.match(sql,/a\.sales_order_id=NEW\.sales_order_id AND a\.id<>NEW\.id/);
assert.match(sql,/product_name text, model_number text, vendor_id uuid, vendor_name text/);
assert.match(purchasing,/d\.vendor_id===demandVendor/);
assert.match(purchasing,/d\.product_name/);
console.log('Consolidated multi-job PO allocation tests passed');
